import itertools
def count(S, ms):
    c=0
    for comps in itertools.product(range(1,ms+1), repeat=S):
        if sum(comps)==128: c+=1
    return c
for S,ms in [(4,32),(4,42),(5,26),(6,22),(8,16),(16,8),(16,32)]:
    print(S,ms,count(S,ms) if ms<=32 else '-')
